 ('circumradius', 'circumradius', 'bán kính đường tròn ngoại tiếp', 'the radius \\(R\\) of the circle through the three vertices.', 'bán kính \\(R\\) của đường tròn đi qua ba đỉnh.', 'Find the circumradius of the triangle.', '\\(R\\)'),
 ('inradius', 'inradius', 'bán kính đường tròn nội tiếp', 'the radius \\(r\\) of the circle inside the triangle touching three sides.', 'bán kính \\(r\\) của đường tròn nằm trong tam giác, tiếp xúc ba cạnh.', 'The inradius is \\(r=S/p\\).', '\\(r\\)'),
