theory += BOX('blue', ('Law of cosines', 'Định lí cô-sin'), M('a^2=b^2+c^2-2bc\\cos A,\\quad b^2=a^2+c^2-2ac\\cos B,\\quad c^2=a^2+b^2-2ab\\cos C'), T('Corollary: \\(\\cos A=\\dfrac{b^2+c^2-a^2}{2bc}\\). It gives an angle when we know three sides. If \\(A=90^\\circ\\) we get the Pythagorean theorem.', 'Hệ quả: \\(\\cos A=\\dfrac{b^2+c^2-a^2}{2bc}\\); dùng để tính góc khi biết ba cạnh. Khi \\(A=90^\\circ\\) ta được định lí Pythagore.'))
theory += '<h3>5.2 %s</h3>' % TI('Law of sines', 'Định lí sin')
theory += BOX('blue', ('Law of sines', 'Định lí sin'), M('\\dfrac{a}{\\sin A}=\\dfrac{b}{\\sin B}=\\dfrac{c}{\\sin C}=2R'), T('\\(R\\) is the circumradius. Use it when you know a side and its opposite angle.', '\\(R\\) là bán kính đường tròn ngoại tiếp. Dùng khi biết một cạnh và góc đối diện với nó.'))
theory += '<h3>5.3 %s</h3>' % TI('Area of a triangle', 'Diện tích tam giác')
theory += BOX('mint', ('Area formulas', 'Các công thức diện tích'), M('S=\\tfrac12ab\\sin C=\\tfrac12bc\\sin A=\\tfrac12ca\\sin B=\\dfrac{abc}{4R}=pr'), M('S=\\sqrt{p(p-a)(p-b)(p-c)},\\qquad p=\\dfrac{a+b+c}{2}\\ \\text{(Heron)}'), T('Also \\(S=\\tfrac12ah_a\\) (base times height).', 'Ngoài ra \\(S=\\tfrac12ah_a\\) (đáy nhân chiều cao chia đôi).'))
theory += '<h3>5.4 %s</h3>' % TI('Solving triangles and applications', 'Giải tam giác và ứng dụng')
theory += BOX('mint', ('Which formula?', 'Chọn công thức nào?'), UL([T('Two sides and the angle between: law of cosines for the third side.', 'Biết hai cạnh và góc xen giữa: dùng định lí cô-sin tính cạnh thứ ba.'), T('Three sides: law of cosines for an angle.', 'Biết ba cạnh: dùng định lí cô-sin tính góc.'), T('A side and two angles: find the third angle (sum \\(180^\\circ\\)), then law of sines.', 'Biết một cạnh và hai góc: tính góc còn lại (tổng \\(180^\\circ\\)), rồi dùng định lí sin.')]))
theory += BOX('yellow', ('Watch out!', 'Lưu ý'), T('For a sine of an obtuse angle, \\(\\sin\\alpha=\\sin(180^\\circ-\\alpha)\\): the law of sines may give two angles. Use the law of cosines to avoid this.', 'Với góc tù, \\(\\sin\\alpha=\\sin(180^\\circ-\\alpha)\\): định lí sin có thể cho hai góc. Dùng định lí cô-sin để tránh nhầm.'))
examples = EXAMPLE(1, ('Basic', 'Cơ bản'), ('Third side', 'Tính cạnh thứ ba'), T('In triangle \\(ABC\\), \\(b=8\\), \\(c=5\\), \\(\\widehat{A}=60^\\circ\\). Find \\(a\\).', 'Tam giác \\(ABC\\) có \\(b=8\\), \\(c=5\\), \\(\\widehat{A}=60^\\circ\\). Tính \\(a\\).'), ('Two sides and the angle between them.', 'Biết hai cạnh và góc xen giữa.'),
  [T('\\(a^2=8^2+5^2-2\\cdot8\\cdot5\\cos60^\\circ=64+25-40=49\\).', '\\(a^2=8^2+5^2-2\\cdot8\\cdot5\\cos60^\\circ=64+25-40=49\\).')], T('\\(a=7\\).', '\\(a=7\\).'))
examples += EXAMPLE(2, ('Basic', 'Cơ bản'), ('Find an angle', 'Tính góc'), T('The sides of a triangle are \\(3,\\ 5,\\ 7\\). Find its largest angle.', 'Ba cạnh của tam giác là \\(3,\\ 5,\\ 7\\). Tính góc lớn nhất.'), ('The largest angle is opposite the longest side, 7.', 'Góc lớn nhất đối diện cạnh dài nhất, 7.'),
  [T('\\(\\cos\\alpha=\\dfrac{3^2+5^2-7^2}{2\\cdot3\\cdot5}=\\dfrac{-15}{30}=-\\dfrac12\\).', '\\(\\cos\\alpha=\\dfrac{3^2+5^2-7^2}{2\\cdot3\\cdot5}=\\dfrac{-15}{30}=-\\dfrac12\\).')], T('\\(\\alpha=120^\\circ\\).', '\\(\\alpha=120^\\circ\\).'))
examples += EXAMPLE(3, ('Intermediate', 'Trung bình'), ('Area three ways', 'Diện tích bằng ba cách'), T('Triangle with sides \\(13,\\ 14,\\ 15\\): find the area \\(S\\), the inradius \\(r\\) and the circumradius \\(R\\).', 'Tam giác có ba cạnh \\(13,\\ 14,\\ 15\\): tính diện tích \\(S\\), bán kính nội tiếp \\(r\\) và bán kính ngoại tiếp \\(R\\).'), ('Heron first, then \\(S=pr\\) and \\(S=\\dfrac{abc}{4R}\\).', 'Heron trước, rồi \\(S=pr\\) và \\(S=\\dfrac{abc}{4R}\\).'),
  [T('\\(p=21\\), \\(S=\\sqrt{21\\cdot8\\cdot7\\cdot6}=\\sqrt{7056}=84\\).', '\\(p=21\\), \\(S=\\sqrt{21\\cdot8\\cdot7\\cdot6}=\\sqrt{7056}=84\\).'), T('\\(r=\\dfrac Sp=\\dfrac{84}{21}=4\\). \\(R=\\dfrac{abc}{4S}=\\dfrac{13\\cdot14\\cdot15}{336}=\\dfrac{2730}{336}=\\dfrac{65}{8}\\).', '\\(r=\\dfrac Sp=\\dfrac{84}{21}=4\\). \\(R=\\dfrac{abc}{4S}=\\dfrac{13\\cdot14\\cdot15}{336}=\\dfrac{2730}{336}=\\dfrac{65}{8}\\).')], T('\\(S=84,\\ r=4,\\ R=\\dfrac{65}{8}\\).', '\\(S=84,\\ r=4,\\ R=\\dfrac{65}{8}\\).'))
assert 21 * 8 * 7 * 6 == 84 ** 2 and abs(13 * 14 * 15 / (4 * 84) - 65 / 8) < 1e-12
examples += EXAMPLE(4, ('Intermediate', 'Trung bình'), ('Solve a triangle', 'Giải tam giác'), T('In triangle \\(ABC\\), \\(a=10\\), \\(\\widehat{B}=45^\\circ\\), \\(\\widehat{C}=75^\\circ\\). Find \\(\\widehat A\\), \\(b\\) and \\(c\\) (round to 0.1).', 'Tam giác \\(ABC\\) có \\(a=10\\), \\(\\widehat{B}=45^\\circ\\), \\(\\widehat{C}=75^\\circ\\). Tính \\(\\widehat A\\), \\(b\\), \\(c\\) (làm tròn đến 0,1).'), ('A side and two angles.', 'Biết một cạnh và hai góc.'),
  [T('\\(\\widehat A=180^\\circ-45^\\circ-75^\\circ=60^\\circ\\).', '\\(\\widehat A=180^\\circ-45^\\circ-75^\\circ=60^\\circ\\).'), T('\\(2R=\\dfrac{10}{\\sin60^\\circ}\\approx11.547\\). \\(b=2R\\sin45^\\circ\\approx8.2\\); \\(c=2R\\sin75^\\circ\\approx11.2\\).', '\\(2R=\\dfrac{10}{\\sin60^\\circ}\\approx11{,}547\\). \\(b=2R\\sin45^\\circ\\approx8{,}2\\); \\(c=2R\\sin75^\\circ\\approx11{,}2\\).')], T('\\(\\widehat A=60^\\circ,\\ b\\approx8.2,\\ c\\approx11.2\\).', '\\(\\widehat A=60^\\circ,\\ b\\approx8{,}2,\\ c\\approx11{,}2\\).'))
_2R = 10 / math.sin(math.radians(60)); assert round(_2R * math.sin(math.radians(45)), 1) == 8.2 and round(_2R * math.sin(math.radians(75)), 1) == 11.2
examples += EXAMPLE(5, ('Advanced', 'Nâng cao'), ('Distance across a river', 'Đo khoảng cách qua sông'), T('To find the distance from \\(A\\) to a tree \\(T\\) across a river, we measure \\(AB=60\\) m, \\(\\widehat{TAB}=75^\\circ\\), \\(\\widehat{TBA}=45^\\circ\\). Find \\(AT\\).', 'Để đo khoảng cách từ \\(A\\) đến cây \\(T\\) bên kia sông, ta đo \\(AB=60\\) m, \\(\\widehat{TAB}=75^\\circ\\), \\(\\widehat{TBA}=45^\\circ\\). Tính \\(AT\\).'), ('Find the angle at \\(T\\), then use the law of sines.', 'Tính góc tại \\(T\\), rồi dùng định lí sin.'),
  [T('\\(\\widehat T=180^\\circ-75^\\circ-45^\\circ=60^\\circ\\).', '\\(\\widehat T=180^\\circ-75^\\circ-45^\\circ=60^\\circ\\).'), T('\\(\\dfrac{AT}{\\sin45^\\circ}=\\dfrac{AB}{\\sin60^\\circ}\\Rightarrow AT=\\dfrac{60\\sin45^\\circ}{\\sin60^\\circ}=20\\sqrt6\\approx49.0\\) m.', '\\(\\dfrac{AT}{\\sin45^\\circ}=\\dfrac{AB}{\\sin60^\\circ}\\Rightarrow AT=\\dfrac{60\\sin45^\\circ}{\\sin60^\\circ}=20\\sqrt6\\approx49{,}0\\) m.')], T('\\(AT\\approx49.0\\) m.', '\\(AT\\approx49{,}0\\) m.'))
assert abs(60 * math.sin(math.radians(45)) / math.sin(math.radians(60)) - 20 * 6 ** .5) < 1e-9

def lvl(P):
    a, b, g, c, (s1, s2, s3, ang), (h1, h2, h3, S), (ar, br, gr), (tv1, tv2), (ssA, ssB) = P['c'], P['b'], P['g'], P['cc'], P['ang'], P['her'], P['area'], P['tv'], P['sine']
    o1 = M4(1, 'In triangle \\(ABC\\), \\(AB=%d\\), \\(AC=%d\\), \\(\\widehat A=%d^\\circ\\). Then \\(BC=\\)…' % (a, b, g), 'Tam giác \\(ABC\\) có \\(AB=%d\\), \\(AC=%d\\), \\(\\widehat A=%d^\\circ\\). Khi đó \\(BC=\\)…' % (a, b, g), str(c), [str(c + 1), str(c - 1), str(a + b), str(c + 2), str(c - 2)], '\\(BC^2=%d^2+%d^2-2\\cdot%d\\cdot%d\\cos%d^\\circ=%d\\).' % (a, b, a, b, g, c * c), '\\(BC^2=%d^2+%d^2-2\\cdot%d\\cdot%d\\cos%d^\\circ=%d\\).' % (a, b, a, b, g, c * c))
    o2 = M4(2, 'A triangle has sides \\(%d,\\ %d,\\ %d\\). The angle opposite the side %d is…' % (s1, s2, s3, s2), 'Tam giác có ba cạnh \\(%d,\\ %d,\\ %d\\). Góc đối diện với cạnh %d bằng…' % (s1, s2, s3, s2), '%d^\\circ' % ang, ['%d^\\circ' % x for x in (30, 45, 60, 90, 120, 150) if x != ang][:3], 'Law of cosines gives \\(\\cos=%s\\).' % fr(F(s1 * s1 + s3 * s3 - s2 * s2, 2 * s1 * s3)), 'Định lí cô-sin cho \\(\\cos=%s\\).' % fr(F(s1 * s1 + s3 * s3 - s2 * s2, 2 * s1 * s3)))
    Sar = F(ar * br, 2) * F(1, 2)
    o3 = M4(3, 'In triangle \\(ABC\\), \\(AB=%d\\), \\(AC=%d\\), \\(\\widehat A=%d^\\circ\\). The area is…' % (ar, br, gr), 'Tam giác \\(ABC\\) có \\(AB=%d\\), \\(AC=%d\\), \\(\\widehat A=%d^\\circ\\). Diện tích bằng…' % (ar, br, gr), fr(Sar), [fr(2 * Sar), fr(Sar + 1), fr(Sar * 2 + 1), fr(Sar + 2)], '\\(S=\\frac12\\cdot%d\\cdot%d\\cdot\\sin%d^\\circ=%s\\).' % (ar, br, gr, fr(Sar)), '\\(S=\\frac12\\cdot%d\\cdot%d\\cdot\\sin%d^\\circ=%s\\).' % (ar, br, gr, fr(Sar)))
    t4 = tf(4, 'In triangle \\(ABC\\), \\(\\dfrac{a}{\\sin A}=%s\\).' % P['tf4'][0], 'Trong tam giác \\(ABC\\), \\(\\dfrac{a}{\\sin A}=%s\\).' % P['tf4'][0], P['tf4'][1], 'The law of sines: \\(\\dfrac{a}{\\sin A}=2R\\).', 'Định lí sin: \\(\\dfrac{a}{\\sin A}=2R\\).')
    t5 = tf(5, 'The area of the triangle with sides \\(%d,\\ %d,\\ %d\\) is %d.' % (h1, h2, h3, S + (0 if tv2 else 2)), 'Diện tích tam giác có ba cạnh \\(%d,\\ %d,\\ %d\\) bằng %d.' % (h1, h2, h3, S + (0 if tv2 else 2)), tv2, 'By Heron the area is %d.' % S, 'Theo công thức Heron diện tích là %d.' % S)
    s6 = sh(6, 'Find the area of the triangle with sides \\(%d,\\ %d,\\ %d\\).' % (h1, h2, h3), 'Tính diện tích tam giác có ba cạnh \\(%d,\\ %d,\\ %d\\).' % (h1, h2, h3), S, 'Heron: \\(S=%d\\).' % S, 'Heron: \\(S=%d\\).' % S)
    s7 = sh(7, 'In triangle \\(ABC\\), \\(BC=%d\\), \\(\\widehat A=%d^\\circ\\), \\(\\widehat B=%d^\\circ\\). Find \\(CA\\).' % (ssA, P['sA'], P['sB']), 'Tam giác \\(ABC\\) có \\(BC=%d\\), \\(\\widehat A=%d^\\circ\\), \\(\\widehat B=%d^\\circ\\). Tính \\(CA\\).' % (ssA, P['sA'], P['sB']), ssB, '\\(CA=\\dfrac{%d\\sin%d^\\circ}{\\sin%d^\\circ}=%d\\).' % (ssA, P['sB'], P['sA'], ssB), '\\(CA=\\dfrac{%d\\sin%d^\\circ}{\\sin%d^\\circ}=%d\\).' % (ssA, P['sB'], P['sA'], ssB))
    return [[o1, o2, o3], [t4, t5], [s6, s7]]
PP = [dict(c=5, b=8, g=60, cc=7, ang=(5, 7, 8, 60), her=(3, 4, 5, 6), area=(6, 8, 30), tv=(0, True), sine=(7, 14), tf4=('2R', True), sA=30, sB=90),
      dict(c=8, b=15, g=60, cc=13, ang=(3, 7, 5, 120), her=(13, 14, 15, 84), area=(10, 8, 150), tv=(0, False), sine=(9, 18), tf4=('\\dfrac{b}{\\sin B}', True), sA=30, sB=90),
      dict(c=3, b=5, g=120, cc=7, ang=(3, 5, 4, 90), her=(5, 5, 6, 12), area=(6, 10, 30), tv=(0, True), sine=(11, 22), tf4=('\\dfrac{c}{\\cos C}', False), sA=30, sB=90)]
for q in PP:
    q['ang'] = tuple(q['ang']); a_, b_, g_, c_ = q['c'], q['b'], q['g'], q['cc']; assert abs(a_ * a_ + b_ * b_ - 2 * a_ * b_ * math.cos(math.radians(g_)) - c_ * c_) < 1e-9
    s1, s2, s3, ang = q['ang']; assert abs((s1 * s1 + s3 * s3 - s2 * s2) / (2 * s1 * s3) - math.cos(math.radians(ang))) < 1e-9
    h1, h2, h3, S = q['her']; p_ = (h1 + h2 + h3) / 2; assert abs(math.sqrt(p_ * (p_ - h1) * (p_ - h2) * (p_ - h3)) - S) < 1e-9
    assert q['sine'][1] == q['sine'][0] * 2 and q['area'][2] in (30, 150)
PP[0]['her'] = (3, 4, 5, 6)
